-- 20 row(s) -> public.destinations
insert into public.destinations (id, name, latitude, longitude, region, province, category, short_description, long_description, image, gallery, best_time, experiences, highlights, rating, elevation, ideal_for, featured, sort_order, published) values
  ('ella', 'Ella', 6.8667, 81.0466, 'Central', 'Uva Province', array['Mountains', 'Adventure', 'Hidden Gems']::text[], 'Where misty mountains, lush tea plantations, and scenic train journeys meet.', 'Nestled in the Central Highlands, Ella is a tranquil mountain village blessed with breathtaking mountain gaps, emerald-green tea estates, cascading waterfalls, and world-renowned hiking trails. The blue train winding across the iconic Nine Arch Bridge is one of the world’s most cinematic travel moments.', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=1200', array['https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=800', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=800', 'https://images.unsplash.com/photo-1586861635167-e5223aadc9fe?auto=format&fit=crop&q=80&w=800']::text[], 'December – April', array['Nine Arch Bridge Train Watch', 'Ella Rock Sunrise Hike', 'Little Adam’s Peak Trek', 'Ravana Falls Dip & Zip Line']::text[], array['Nine Arch Bridge', 'Ella Rock', 'Ravana Falls', 'Demodara Loop']::text[], 4.9, '1,041 m', array['Hikers', 'Photographers', 'Nature Lovers']::text[], true, 0, true),
  ('sigiriya', 'Sigiriya', 7.957, 80.7603, 'Cultural Triangle', 'Central Province', array['Culture', 'Adventure']::text[], 'An ancient fortress of granite soaring 200 meters above tropical jungle plains.', 'Sigiriya (Lion Rock) is an awe-inspiring UNESCO World Heritage Site featuring 5th-century royal palace ruins, ancient water gardens, delicate frescoes, and the dramatic Lion Gate. Rising abruptly from the jungle canopy, it offers unmatched panoramic views at dawn.', 'https://images.unsplash.com/photo-1586861635167-e5223aadc9fe?auto=format&fit=crop&q=80&w=1200', array['https://images.unsplash.com/photo-1586861635167-e5223aadc9fe?auto=format&fit=crop&q=80&w=800', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&q=80&w=800']::text[], 'January – September', array['Sunrise Climb at Pidurangala Rock', 'Exploring Ancient Water Gardens', 'Sigiriya Frescoes Discovery', 'Elephant Safari at Nearby Minneriya']::text[], array['Lion Rock Citadel', 'Frescoes Gallery', 'Mirror Wall', 'Pidurangala Viewpoint']::text[], 4.95, '349 m', array['History Buffs', 'Explorers', 'Culture Seekers']::text[], true, 1, true),
  ('galle', 'Galle Fort', 6.0535, 80.221, 'South', 'Southern Province', array['Culture', 'Beaches', 'Food']::text[], 'Cobblestone streets, Dutch colonial ramparts, boutique cafés, and ocean breezes.', 'Galle Fort is a living historic fortress jutting into the Indian Ocean. Built first by the Portuguese and fortified by the Dutch in the 17th century, today its enclosed streets are lined with chic artisan boutiques, heritage hotels, gemstone galleries, and oceanfront rampart walks.', 'https://images.unsplash.com/photo-1552465011-b4e21bf6e79a?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'November – April', array['Sunset Rampart Walk', 'Dutch Reformed Church Tour', 'Artisan Jewelry & Gem Shopping', 'Seafood Dining in Colonial Courtyards']::text[], array['Galle Lighthouse', 'Dutch Clock Tower', 'Flag Rock', 'Pedlar Street']::text[], 4.88, null, array['Couples', 'Architecture Enthusiasts', 'Foodies']::text[], true, 2, true),
  ('mirissa', 'Mirissa', 5.9483, 80.4578, 'South', 'Southern Province', array['Beaches', 'Wildlife', 'Adventure']::text[], 'Golden crescent beaches, blue whale watching, coconut tree hills, and sunset vibes.', 'Mirissa is the quintessential tropical paradise on Sri Lanka’s south coast. Famed globally for blue whale sightings in the Indian Ocean, Mirissa boasts tranquil sandy bays, surf points, coconut-fringed hills, and lively beachside seafood barbecues under the stars.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'November – April', array['Blue Whale & Dolphin Safari', 'Coconut Tree Hill Sunset Photo', 'Secret Beach Day Trip', 'Surfing at Mirissa Point']::text[], array['Coconut Tree Hill', 'Secret Beach', 'Parrot Rock', 'Mirissa Harbour']::text[], 4.85, null, array['Beach Lovers', 'Wildlife Safaris', 'Surfers']::text[], true, 3, true),
  ('kandy', 'Kandy', 7.2906, 80.6337, 'Central', 'Central Province', array['Culture', 'Food']::text[], 'The sacred hill capital surrounded by misty forests, lakes, and ancient temples.', 'Kandy was the last royal capital of Sri Lankan kings. Set around a peaceful central lake and framed by tropical mountain ridges, it holds the revered Temple of the Sacred Tooth Relic. Kandy comes alive during the Esala Perahera festival with traditional dancers and torchlit processions.', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'December – April', array['Temple of the Tooth Relic Evening Ceremony', 'Stroll at Royal Botanical Gardens Peradeniya', 'Kandyan Traditional Dance Performance', 'Kandy Lake Serene Sunset Walk']::text[], array['Temple of the Tooth', 'Peradeniya Gardens', 'Kandy Lake', 'Bahirawakanda Buddha']::text[], 4.82, '500 m', array['Culture Seekers', 'Spiritual Travelers', 'Families']::text[], true, 4, true),
  ('jaffna', 'Jaffna', 9.6615, 80.0255, 'North', 'Northern Province', array['Culture', 'Hidden Gems', 'Food']::text[], 'Vibrant Tamil culture, golden kovils, palmyra palms, and untouched northern islands.', 'Jaffna offers a rich, distinct cultural realm in the far north of Sri Lanka. With intricate Hindu temples like Nallur Kandaswamy, historical Dutch forts, shallow blue lagoons, and delicious unique spicy Jaffna crab curry, it is a fascinating haven for authentic explorers.', 'https://images.unsplash.com/photo-1608933221980-dfc7dd884fbf?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'January – September', array['Nallur Kandaswamy Kovil Blessing', 'Ferried Day Trip to Delft Island Wild Horses', 'Tasting Spicy Jaffna Crab Curry', 'Exploring Jaffna Fort at Sunset']::text[], array['Nallur Kovil', 'Delft Island', 'Jaffna Fort', 'Keerimalai Springs']::text[], 4.78, null, array['Off-the-beaten-path Explorers', 'Cultural Enthusiasts']::text[], true, 5, true),
  ('yala', 'Yala National Park', 6.3725, 81.5168, 'South', 'Southern/Uva Province', array['Wildlife', 'Adventure']::text[], 'The world’s highest density of leopards alongside wild elephants, sloths, and coastal dunes.', 'Yala National Park is Sri Lanka’s premier wilderness sanctuary. Spanning scrub jungles, brackish lagoons, and coastline, Yala is world-famous for elusive Sri Lankan leopards, wild elephant herds, sloth bears, crocodiles, and over 200 bird species.', 'https://images.unsplash.com/photo-1549366021-9f761d450615?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'February – July', array['Dawn 4x4 Leopard Safari', 'Elephant Herd Tracking', 'Wild Coastal Dune Photography', 'Luxury Glamping Under the Stars']::text[], array['Block 1 Leopard Sanctuary', 'Sithulpawwa Rock Temple', 'Patnanangala Beach']::text[], 4.92, null, array['Wildlife Photographers', 'Safari Seekers', 'Adventurers']::text[], false, 6, true),
  ('nuwara-eliya', 'Nuwara Eliya', 6.9497, 80.7891, 'Central', 'Central Province', array['Mountains', 'Culture', 'Food']::text[], '“Little England” surrounded by rolling tea valleys, colonial country houses, and cool mountain air.', 'Sitting at 1,868 meters elevation, Nuwara Eliya is Sri Lanka’s cool-climate tea capital. Surrounded by terraced Ceylon tea plantations, cascades, golf courses, and Tudor-style colonial villas, it feels like a timeless highland retreat.', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'February – May', array['High Tea at Colonial Grand Hotel', 'Pedro Tea Factory Processing Tour', 'Boating on Gregory Lake', 'Horton Plains World’s End Trek']::text[], array['Gregory Lake', 'Pedro Tea Estate', 'Victoria Park', 'Post Office Heritage']::text[], 4.81, '1,868 m', array['Tea Lovers', 'Highland Escape', 'Relaxation']::text[], false, 7, true),
  ('arugam-bay', 'Arugam Bay', 6.8413, 81.8358, 'East', 'Eastern Province', array['Beaches', 'Adventure', 'Food']::text[], 'World-famous right-hand point breaks, bohemian beach cafes, and wild elephant lagoons.', 'Arugam Bay on the laid-back eastern coast is legendary among international surfers. Known for long point breaks like Main Point and Elephant Rock, Arugam Bay mixes surf culture, beachfront reggae fires, and wildlife safaris in nearby Kumana and Panama.', 'https://images.unsplash.com/photo-1502680390469-be75c86b636f?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'May – September', array['Dawn Surf Session at Main Point', 'Lagoon Safari at Pottuvil', 'Sunset at Elephant Rock', 'Beachside Yoga & Healthy Smoothie Bowls']::text[], array['Main Point Surf Break', 'Elephant Rock', 'Pottuvil Lagoon', 'Whiskey Point']::text[], 4.87, null, array['Surfers', 'Backpackers', 'Boho Travelers']::text[], false, 8, true),
  ('trincomalee', 'Trincomalee', 8.5874, 81.2152, 'East', 'Eastern Province', array['Beaches', 'Culture', 'Wildlife']::text[], 'Crystal blue waters, Pigeon Island marine park, cliffside Hindu temples, and blue whales.', 'Trincomalee boasts one of the world’s finest natural deep-water harbors, tranquil white sand beaches at Nilaveli, vibrant coral reefs at Pigeon Island National Park, and the ancient Koneswaram Hindu Temple perching on Swami Rock cliff.', 'https://images.unsplash.com/photo-1512100356356-de1b84283e18?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'April – October', array['Snorkeling with Blacktip Reef Sharks at Pigeon Island', 'Koneswaram Temple Cliffside Visit', 'Nilaveli Beach Relaxation', 'Whale Watching in Trinco Bay']::text[], array['Pigeon Island', 'Koneswaram Temple', 'Nilaveli Beach', 'Fort Frederick']::text[], 4.86, null, array['Divers & Snorkelers', 'Beach Enthusiasts', 'History Explorers']::text[], false, 9, true),
  ('anuradhapura', 'Anuradhapura', 8.3114, 80.4037, 'Cultural Triangle', 'North Central Province', array['Culture', 'Hidden Gems']::text[], 'Sri Lanka’s sacred first ancient capital with colossal white stupas and a 2,300-year-old sacred fig tree.', 'Anuradhapura was the spiritual and political cradle of ancient Sri Lankan civilization for over 1,300 years. Spanning vast green parklands, its towering bell-shaped stupas rival the Egyptian pyramids in architectural grandeur.', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'May – September', array['Cycling Among Ancient Stupas', 'Paying Homage at Jaya Sri Maha Bodhi Tree', 'Ruwanwelisaya Stupa Evening Illumination', 'Mihintale Sunset Pilgrimage']::text[], array['Ruwanwelisaya', 'Jaya Sri Maha Bodhi', 'Jetavanaramaya', 'Mihintale Rock']::text[], 4.84, null, array['Pilgrims', 'Historians', 'Cyclists']::text[], false, 10, true),
  ('polonnaruwa', 'Polonnaruwa', 7.9403, 81.0188, 'Cultural Triangle', 'North Central Province', array['Culture', 'Adventure']::text[], 'Restored royal palaces, stone-carved Buddha statues, and jungle ruins best explored by bike.', 'Polonnaruwa succeeded Anuradhapura as Sri Lanka’s medieval capital in the 11th century. Remarkably preserved, its archaeological park contains grand audience halls, royal baths, and the breathtaking Gal Vihara—four monumental Buddha images carved into a single granite wall.', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'May – September', array['Bicycle Tour of Royal Ruins', 'Gal Vihara Rock Sculpture Admiration', 'Parakrama Samudra Lake Sunset View', 'Monkey Kingdom Wildlife Tour']::text[], array['Gal Vihara', 'Royal Palace of Parakramabahu', 'Vatadage', 'Parakrama Samudra']::text[], 4.83, null, array['Archaeology Lovers', 'Bicycle Explorers']::text[], false, 11, true),
  ('udawalawe', 'Udawalawe National Park', 6.4746, 80.8987, 'South', 'Sabaragamuwa Province', array['Wildlife', 'Adventure']::text[], 'Guaranteed elephant encounters in open savannah landscapes resembling East Africa.', 'Udawalawe is Sri Lanka’s top park for observing wild Sri Lankan elephants in their natural habitat. Centered around a vast reservoir, its grassy grasslands allow close-up observations of wild herds, calves playing, waterbirds, and peacocks.', 'https://images.unsplash.com/photo-1581852017103-68accd5509b6?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'Year-round (Best Dec – May)', array['Open Jeep Safari for Elephant Herds', 'Visiting Udawalawe Elephant Transit Home', 'Reservoir Sunset Bird Watching']::text[], array['Elephant Herds', 'Udawalawe Reservoir', 'Elephant Transit Home']::text[], 4.89, null, array['Families', 'Animal Lovers', 'Safari Fans']::text[], false, 12, true),
  ('horton-plains', 'Horton Plains & World’s End', 6.8018, 80.8037, 'Central', 'Central Province', array['Mountains', 'Adventure', 'Hidden Gems']::text[], 'Wind-swept misty grasslands ending in a sheer 880-meter vertical drop at World’s End.', 'Sitting on a high altitude plateau over 2,100 meters above sea level, Horton Plains National Park is a unique montane ecosystem of cloud forest, dwarf bamboo, and wild sambar deer, culminating at the terrifying drop of World’s End cliff.', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'January – April (Early mornings)', array['9km Loop Trek to World’s End & Baker’s Falls', 'Spotting Sambar Deer in the Mist', 'Highland Bird Watching']::text[], array['World’s End', 'Baker’s Falls', 'Mini World’s End', 'Chimapani Plain']::text[], 4.86, '2,100 m', array['Trekkers', 'Photographers', 'Highland Explorers']::text[], false, 13, true),
  ('weligama', 'Weligama', 5.9723, 80.4289, 'South', 'Southern Province', array['Beaches', 'Adventure', 'Food']::text[], 'The surf capital for beginners, traditional stilt fishermen, and modern beach clubs.', 'Weligama (meaning Sandy Village) features a vast sheltered bay with gentle, consistent beach break waves ideal for beginner and intermediate surfers. It is also famous for iconic stilt fishermen perched on wooden poles in the sea.', 'https://images.unsplash.com/photo-1502680390469-be75c86b636f?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'November – April', array['Beginner Surfing Lessons in Weligama Bay', 'Photographing Traditional Stilt Fishermen', 'Catamaran Sailing & Stand-up Paddleboarding', 'Fresh Catch Seafood Dinners']::text[], array['Weligama Surf Bay', 'Taprobane Island', 'Stilt Fishermen Points']::text[], 4.8, null, array['Beginner Surfers', 'Sunseekers', 'Beach Lifestyle']::text[], false, 14, true),
  ('dambulla', 'Dambulla Cave Temple', 7.8742, 80.6511, 'Cultural Triangle', 'Central Province', array['Culture']::text[], 'Five ancient rock caverns filled with 153 gilded Buddha statues and vibrant ceiling murals.', 'Dambulla Royal Cave Temple is the largest, best-preserved cave temple complex in Sri Lanka. Dating back to the 1st century BCE, five magnificent caves house century-old statues and colorful frescoes painted directly onto the subterranean rock walls.', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'Year-round', array['Exploring 5 Illuminated Sacred Rock Caves', 'Panoramas over Sigiriya Rock from the Summit', 'Golden Temple Museum Tour']::text[], array['Cave of the Divine King', 'Golden Buddha Statue', 'Rock Murals']::text[], 4.81, null, array['Culture Lovers', 'Spiritual Explorers']::text[], false, 15, true),
  ('colombo', 'Colombo', 6.9271, 79.8612, 'West', 'Western Province', array['Culture', 'Food']::text[], 'Sri Lanka’s energetic commercial capital blending colonial charm, glass skyscrapers, and street food.', 'Colombo is a vibrant oceanfront metropolis where colonial British and Dutch architecture stand beside contemporary rooftop bars, bustling Pettah markets, peaceful Buddhist temples on Beira Lake, and oceanfront Galle Face Green promenade.', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'December – March', array['Galle Face Green Sunset Street Food Stroll', 'Gangaramaya Temple Visit on Beira Lake', 'Shopping at Dutch Hospital Shopping Precinct', 'Rooftop Cocktail with Indian Ocean Sunset View']::text[], array['Gangaramaya Temple', 'Galle Face Green', 'Pettah Market', 'Lotus Tower']::text[], 4.75, null, array['Urban Explorers', 'Foodies', 'Shoppers']::text[], false, 16, true),
  ('knuckles', 'Knuckles Mountain Range', 7.4583, 80.7917, 'Central', 'Central Province', array['Mountains', 'Adventure', 'Hidden Gems']::text[], 'Unspoiled UNESCO cloud forest wilderness named after its fist-like mountain peaks.', 'The Knuckles Conservation Forest is a rugged bio-diverse haven of cloud forests, hidden waterfalls, endemic wildlife, and isolated traditional mountain hamlets. Perfect for serious trekkers wanting untamed nature.', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'June – September & December – March', array['Multi-day Wilderness Trekking', 'Wild Waterfall Swimming', 'Camping Under Starry Highland Skies', 'Meemure Remote Village Visit']::text[], array['Meemure Village', 'Corbett’s Gap', 'Mini World’s End Knuckles', 'Dunamalix Falls']::text[], 4.91, '1,906 m', array['Advanced Trekkers', 'Eco Travelers', 'Campers']::text[], false, 17, true),
  ('bentota', 'Bentota', 6.4239, 79.9983, 'West', 'Southern Province', array['Beaches', 'Adventure']::text[], 'Luxury beach resorts, golden river lagoons, water sports, and Geoffrey Bawa gardens.', 'Bentota is Sri Lanka’s water sports capital where the tranquil Bentota Ganga river meets the ocean. Known for luxury beachfront resorts, jet-skiing, turtle conservation hatcheries, and Brief Garden designed by Bevis Bawa.', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'November – April', array['Madu River Mangrove Safari', 'Jet Skiing & Banana Boat Watersports', 'Brief Garden Estate Tour', 'Kosgoda Sea Turtle Hatchery Visit']::text[], array['Bentota River Lagoon', 'Brief Garden', 'Kosgoda Turtle Sanctuary']::text[], 4.79, null, array['Families', 'Watersport Fans', 'Resort Travelers']::text[], false, 18, true),
  ('haputale', 'Haputale', 6.7686, 80.9572, 'Central', 'Uva Province', array['Mountains', 'Hidden Gems']::text[], 'High mountain ridge town offering views extending all the way to the southern coastline.', 'Perched on a sheer mountain ledge, Haputale offers dramatic views across Sri Lanka’s southern plains. It is home to Lipton’s Seat—where Sir Thomas Lipton surveyed his vast tea empire—and the serene Adisham Monastery.', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=1200', '{}'::text[], 'April – August', array['Lipton’s Seat Viewpoint Sunrise Trek', 'Adisham Benedictine Monastery Visit', 'Diyaluma Waterfall Natural Pool Dip']::text[], array['Lipton’s Seat', 'Adisham Bungalow', 'Diyaluma Falls']::text[], 4.88, '1,431 m', array['Tea Connoisseurs', 'Quiet Mountain Lovers']::text[], false, 19, true)
