  ('beach-escapes', 'Beach Escapes', 'Beaches', 'Golden sands, turquoise waters & coconut palms', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=800', 'Unwind along 1,300+ km of tropical coastline, from southern surf bays to serene eastern white sand beaches.', 0, true),
  ('wild-sri-lanka', 'Wild Sri Lanka', 'Wildlife', 'Leopards, wild elephants & marine giants', 'https://images.unsplash.com/photo-1549366021-9f761d450615?auto=format&fit=crop&q=80&w=800', 'Embark on thrilling 4x4 safaris in Yala & Wilpattu or spot blue whales glinting in the Indian Ocean.', 1, true),
  ('ancient-sri-lanka', 'Ancient Sri Lanka', 'Culture', '2,500 years of royal kingdoms & rock fortresses', 'https://images.unsplash.com/photo-1586861635167-e5223aadc9fe?auto=format&fit=crop&q=80&w=800', 'Explore UNESCO rock fortresses, carved stone Buddhas, and sacred stupas towering above jungle plains.', 2, true),
  ('mountain-adventures', 'Mountain Adventures', 'Mountains', 'Misty tea valleys, cloud forests & scenic trains', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=800', 'Hike sunrise peaks, ride the famous blue highland train, and swim in natural waterfall pools.', 3, true),
  ('food-and-culture', 'Food & Culture', 'Food', 'Aromatic spices, hopper breakfasts & street feasts', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=800', 'Savor fragrant coconut curries, fresh seafood, spicy kottu roti, and world-renowned Ceylon tea.', 4, true),
  ('hidden-sri-lanka', 'Hidden Sri Lanka', 'Hidden Gems', 'Secret waterfalls, remote peaks & island gems', 'https://images.unsplash.com/photo-1608933221980-dfc7dd884fbf?auto=format&fit=crop&q=80&w=800', 'Venture beyond the guidebook to isolated mountain plateaus, wild river canyons, and serene islands.', 5, true)
