insert into public.featured_experiences (id, title, subtitle, location, duration, category, image, description, highlights, recommended_time, rating, sort_order, published) values
  ('sunrise-ella', 'Sunrise at Ella', 'Watch the mountains wake up above the clouds', 'Ella, Central Highlands', '3–4 Hours', 'Mountains', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=1000', 'Rise before dawn and hike up Little Adam’s Peak or Ella Rock as golden sunlight pierces mist floating across emerald tea valleys.', array['360-degree mountain gap panoramas', 'Tea estate walk in morning dew', 'Watch the blue train cross Nine Arch Bridge']::text[], '5:30 AM – 8:30 AM', 4.98, 0, true),
  ('safari-yala', 'Safari in Yala', 'Experience Sri Lanka’s wild side up close', 'Yala National Park', 'Half Day / Full Day', 'Wildlife', 'https://images.unsplash.com/photo-1549366021-9f761d450615?auto=format&fit=crop&q=80&w=1000', 'Navigate dusty jungle tracks in an open-top 4x4 jeep to track elusive Sri Lankan leopards, wild elephant herds, sloth bears, and crocodiles.', array['Highest leopard density in the world', 'Private expert wilderness tracker', 'Wild coastal dune coffee break']::text[], '6:00 AM or 3:00 PM', 4.94, 1, true),
  ('sunset-mirissa', 'Sunset in Mirissa', 'Golden beaches and unforgettable ocean sunsets', 'Mirissa, South Coast', '2–3 Hours', 'Beaches', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=1000', 'Climb Coconut Tree Hill as the sun dips into the Indian Ocean, painting the palm fronds and crashing waves in fiery violet and amber hues.', array['Iconic Coconut Tree Hill viewpoint', 'Fresh grilled catch of the day at beachside cafes', 'Calm turquoise bay swimming']::text[], '5:00 PM – 7:00 PM', 4.92, 2, true),
  ('walk-galle-fort', 'Walk Through Galle Fort', 'Discover colonial architecture, cafés and stories', 'Galle Fort, South Coast', '2–3 Hours', 'Culture', 'https://images.unsplash.com/photo-1552465011-b4e21bf6e79a?auto=format&fit=crop&q=80&w=1000', 'Wander cobblestone lanes enclosed by 400-year-old Dutch ramparts, visiting artisan jewelers, boutique espresso bars, and historic lighthouses.', array['Guided rampart heritage walk at golden hour', 'Artisan gem & spiced tea shopping', 'Colonial courtyard gourmet dining']::text[], '4:00 PM – 7:00 PM', 4.9, 3, true)
