-- 6 row(s) -> public.articles
insert into public.articles (id, title, category, published_at, read_time, image, snippet, author_name, author_avatar, author_role, content, sort_order, published) values
  ('sunrise-locations-sri-lanka', '10 Places to Watch Sunrise in Sri Lanka', 'INSPIRATION', '2026-02-12', '6 min read', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=800', 'From the peaks of Adam’s Peak to the silent shores of Trincomalee, discover where morning light transforms the island into liquid gold.', 'Nishan Fernando', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=200', 'Lead Explorer', array['There is a quiet magic to Sri Lankan mornings. Long before the island awakens, clouds gather in violet valleys and fishing catamarans cut through silent sea mist.', '1. Little Adam’s Peak, Ella: A gentle 45-minute climb rewarded by 360-degree views of morning light spilling over Ella Gap.', '2. Pidurangala Rock, Sigiriya: The ultimate viewpoint to watch the sun rise directly behind the ancient Lion Rock fortress.', '3. Swami Rock, Trincomalee: Perch high on the eastern cliffs as devotional prayers echo from Koneswaram Temple into the dawn sky.', '4. World’s End, Horton Plains: Arrive by 6:00 AM before clouds cover the sheer 880m vertical cliff drop.']::text[], 0, true),
  ('ultimate-ella-guide', 'The Ultimate Ella Travel Guide: Mountains, Trains & Tea', 'DESTINATION GUIDES', '2026-01-28', '8 min read', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=800', 'Everything you need to know about hiking Ella Rock, capturing Nine Arch Bridge, finding secret waterfalls, and enjoying mountain cafe culture.', 'Dilini Senanayake', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&q=80&w=200', 'Cultural Historian', array['Ella has evolved from a sleepy railway stop into the crown jewel of Sri Lanka’s highlands. At an elevation of 1,041 meters, the air is crisp, the tea is fresh, and every trail leads to breathtaking vistas.', 'How to catch the train over Nine Arch Bridge: The blue passenger train passes approximately 6 times daily. Arrive 30 minutes early to secure a spot along the tea estate slopes.', 'Hike Ella Rock: A 4-hour return trek starting along train tracks before ascending through rubber trees and eucalyptus groves.', 'Where to eat: Enjoy organic farm-to-table dining, spiced iced chais, and fresh roti in cozy hillside spots.']::text[], 1, true),
  ('best-beaches-sri-lanka', 'Best Beaches in Sri Lanka: From Surf Points to Secret Bays', 'COASTAL', '2026-01-15', '7 min read', 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&q=80&w=800', 'Whether you want world-class waves, serene palm fringed bays, or blue whale excursions, here is your definitive beach roadmap.', 'Kavinda Perera', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&q=80&w=200', 'Surf & Ocean Guide', array['With over 1,300 kilometers of tropical coastline, Sri Lanka is a year-round beach haven thanks to its dual monsoon seasons.', 'South Coast (Best Nov - Apr): Hiriketiya for surf and horseshoe bay vibes, Mirissa for sunsets and whales, Tangalle for untouched quiet beaches.', 'East Coast (Best May - Sep): Nilaveli for powdery white sand, Arugam Bay for world-renowned right-hand point breaks, Pasikuda for shallow calm turquoise lagoons.']::text[], 2, true),
  ('guide-sri-lankan-food', 'A Guide to Sri Lankan Food: Curries, Hoppers & Spices', 'CULINARY', '2025-12-20', '5 min read', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=800', 'Unpack the rich flavors of Ceylon cinnamon, toasted coconut, clay-pot fish curry, crispy egg hoppers, and spicy kottu roti.', 'Anushka Jaywardena', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&q=80&w=200', 'Culinary Curator', array['Sri Lankan cuisine is a complex celebration of roasted spices, fresh coconut milk, curry leaves, pandan, and tropical heat.', 'Must-try dishes:', '• Egg Hoppers (Appa): Bowl-shaped fermented rice flour crêpes with a soft-boiled egg in the center.', '• Kottu Roti: Shredded flatbread flash-fried on a flat iron griddle with vegetables, egg, spices, and chicken or seafood.', '• Black Pork Curry: Tender pork slow-braised with dark-roasted spices and goraka (garcinia).']::text[], 3, true),
  ('wildlife-safaris-where-to-go', 'Wildlife Safaris: Where to Go for Leopards, Elephants & Whales', 'WILDLIFE', '2025-12-05', '9 min read', 'https://images.unsplash.com/photo-1549366021-9f761d450615?auto=format&fit=crop&q=80&w=800', 'Navigating Sri Lanka’s 26 national parks to plan the perfect safari journey for every season.', 'Nishan Fernando', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&q=80&w=200', 'Lead Explorer', array['Sri Lanka packs more wildlife diversity per square kilometer than almost any country in Asia.', 'Yala: Best for elusive leopards and sloth bears.', 'Minneriya & Kaudulla: Home to "The Gathering"—up to 300 Asian elephants assembling around reservoir shores.', 'Wilpattu: Dense jungle & tranquil lakes with fewer safari crowds.']::text[], 4, true),
  ('hidden-gems-visit', 'Hidden Gems You Should Visit Before Everyone Else Does', 'OFF THE BEATEN PATH', '2025-11-18', '6 min read', 'https://images.unsplash.com/photo-1608933221980-dfc7dd884fbf?auto=format&fit=crop&q=80&w=800', 'Step off the main tourist trail to explore secret cloud forests, ancient cave sanctuaries, and wild island archipelagos.', 'Dilini Senanayake', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&q=80&w=200', 'Cultural Historian', array['Beyond the iconic Sigiriya and Ella lies a secret Sri Lanka preserved in quiet valleys and untouched coastlines.', 'Discover Riverston in the Knuckles, boat safaris in Gal Oya, and wild horses galloping on Delft Island.']::text[], 5, true)
on conflict (id) do update set
  title = excluded.title,
  category = excluded.category,
  published_at = excluded.published_at,
  read_time = excluded.read_time,
  image = excluded.image,
  snippet = excluded.snippet,
  author_name = excluded.author_name,
  author_avatar = excluded.author_avatar,
  author_role = excluded.author_role,
  content = excluded.content,
  sort_order = excluded.sort_order,
