  updated_at = now();

-- 8 row(s) -> public.hidden_gems
insert into public.hidden_gems (id, name, region, image, description, why_visit, tag, sort_order, published) values
  ('riverston', 'Riverston Peak & Pitawala Pathana', 'Central Highlands', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=800', 'A breezy high-altitude plateau in the Knuckles range featuring dramatic mini World’s End precipices and wind-swept cloud forests.', 'Fewer tourists, misty mountain gaps, and pristine trekking trails.', 'Cloud Forest Peak', 0, true),
  ('gal-oya', 'Gal Oya National Park', 'Eastern Wilderness', 'https://images.unsplash.com/photo-1581852017103-68accd5509b6?auto=format&fit=crop&q=80&w=800', 'The only national park in Sri Lanka where you can take a boat safari to watch wild elephants swimming between reservoir islands.', 'Swimming elephants, boat safaris & Vedda indigenous walks.', 'Boat Safari Haven', 1, true),
  ('delft-island', 'Delft Island (Neduntheevu)', 'Far North', 'https://images.unsplash.com/photo-1608933221980-dfc7dd884fbf?auto=format&fit=crop&q=80&w=800', 'A remote coral-fringed island off Jaffna inhabited by wild ponies descended from Dutch colonial horses and coral walls.', 'Wild horses, baobab trees & ancient Portuguese coral ruins.', 'Wild Pony Island', 2, true),
  ('belilena', 'Belilena Prehistoric Cave', 'Sabaragamuwa', 'https://images.unsplash.com/photo-1588598198321-9735fd52455b?auto=format&fit=crop&q=80&w=800', 'A cavern hidden behind a waterfall where 30,000-year-old human fossils of Balangoda Man were discovered in deep jungle.', 'Prehistoric anthropology & waterfall cave hiking.', 'Prehistoric Cave', 3, true),
  ('bambarakanda', 'Bambarakanda Waterfall', 'Uva Province', 'https://images.unsplash.com/photo-1546708973-b339540b5162?auto=format&fit=crop&q=80&w=800', 'Sri Lanka’s highest waterfall, plummeting 263 meters through pine forests into a cold mountain basin.', 'Tallest waterfall in Sri Lanka surrounded by pine woods.', 'Tallest Waterfall', 4, true),
  ('madulsima', 'Madulsima Mini World’s End', 'Passara Ridge', 'https://images.unsplash.com/photo-1586861635167-e5223aadc9fe?auto=format&fit=crop&q=80&w=800', 'A dizzying ridge drop over 1,000 meters above eastern tea valleys, where clouds roll right beneath your feet.', 'Sea of clouds, cliffside camping & spectacular vistas.', 'Sea of Clouds Ridge', 5, true),
  ('kudumbigala', 'Kudumbigala Monastery', 'Eastern Jungle', 'https://images.unsplash.com/photo-1578632767115-351597cf2477?auto=format&fit=crop&q=80&w=800', 'An ancient rock monastery dating back to 246 BCE, surrounded by wildlife sanctuary wilderness near Arugam Bay.', 'Cylindrical stupa, jungle tranquility & ocean views.', 'Rock Monastery Sanctuary', 6, true),
  ('kalpitiya', 'Kalpitiya Peninsula', 'North West Coast', 'https://images.unsplash.com/photo-1502680390469-be75c86b636f?auto=format&fit=crop&q=80&w=800', 'A windy coastal strip separating lagoon and sea, world-famous for kitesurfing and dolphin pods in the thousands.', 'Kitesurfing, spinner dolphin pods & pristine sandbars.', 'Kitesurf & Dolphin Haven', 7, true)
on conflict (id) do update set
  name = excluded.name,
