  ('p2', 'The Golden Lion Rock', 'Sigiriya', 'Heritage', 'https://images.unsplash.com/photo-1586861635167-e5223aadc9fe?auto=format&fit=crop&q=80&w=800', 'An ancient granite palace fortress rising 200m above the jungle canopy at sunrise.', 'landscape', 1, true),
