insert into public.pillars (id, icon, title, description, sort_order, published) values
  ('local-knowledge', 'Users', 'Local Knowledge', 'Discover Sri Lanka through the eyes of island natives who possess deep generational heritage, secret trails, and insider connections.', 0, true),
  ('authentic-experiences', 'Compass', 'Authentic Experiences', 'Go beyond predictable tourist hotspots. Access secluded waterfalls, ancestral spice gardens, and private cultural encounters.', 1, true),
  ('flexible-journeys', 'Sliders', 'Flexible Journeys', 'Build every day around your rhythm and curiosity—from high-energy mountain climbs to unhurried beach stays.', 2, true),
  ('responsible-travel', 'Leaf', 'Responsible Travel', 'Explore while actively respecting wildlife habitats, conserving fragile ecosystems, and empowering rural island communities.', 3, true)
